-- Load Strategy Comparison Warehouse SQL Dump
-- Compatible with MySQL, PostgreSQL, and SQLite

SET FOREIGN_KEY_CHECKS = 0;

-- Table: customers (25 rows)
DROP TABLE IF EXISTS customers;
CREATE TABLE customers (
    customer_id VARCHAR(255),
    name VARCHAR(255),
    email VARCHAR(255),
    country VARCHAR(255),
    created_at VARCHAR(255)
);

-- Table: products (15 rows)
DROP TABLE IF EXISTS products;
CREATE TABLE products (
    product_id VARCHAR(255),
    product_name VARCHAR(255),
    category VARCHAR(255),
    unit_price DOUBLE
);

-- Table: orders (132 rows)
DROP TABLE IF EXISTS orders;
CREATE TABLE orders (
    order_id VARCHAR(255),
    customer_id VARCHAR(255),
    product_id VARCHAR(255),
    quantity BIGINT,
    order_amount DOUBLE,
    order_status VARCHAR(255),
    order_date VARCHAR(255),
    updated_at VARCHAR(255),
    run_id VARCHAR(255),
    source_file VARCHAR(255)
);

-- Table: order_status_history (171 rows)
DROP TABLE IF EXISTS order_status_history;
CREATE TABLE order_status_history (
    history_id VARCHAR(255),
    order_id VARCHAR(255),
    order_status VARCHAR(255),
    updated_at VARCHAR(255),
    run_id VARCHAR(255),
    source_file VARCHAR(255)
);

-- Table: rejects (207 rows)
DROP TABLE IF EXISTS rejects;
CREATE TABLE rejects (
    reject_id VARCHAR(255),
    run_id VARCHAR(255),
    source_file VARCHAR(255),
    source_line BIGINT,
    reject_reason VARCHAR(255),
    raw_payload VARCHAR(255),
    created_at VARCHAR(255)
);

-- Table: run_log (10 rows)
DROP TABLE IF EXISTS run_log;
CREATE TABLE run_log (
    run_id VARCHAR(255),
    strategy VARCHAR(255),
    start_time VARCHAR(255),
    end_time VARCHAR(255),
    input_count BIGINT,
    output_count BIGINT,
    rejected_count BIGINT,
    status VARCHAR(255),
    failure_reason VARCHAR(255)
);

SET FOREIGN_KEY_CHECKS = 1;
